    if (k === ADDR.builderMine) return { name: "Builder Mine (mining pots)", kind: "infra" };
    if (ADDR.argusPortals.includes(k) || k === "0xeed7559b8a6abf64427dc41cb5cc6400109c5d93") return { name: "Argus", kind: "infra" };
