      var clean = String(text).replace(/https?:\/\/\S+|\b\S+\.(app|com|me|world)\/\S*/g, "").replace(/0x[0-9a-fA-F]{40}/g, "").replace(/[♡♥✨☀✦]|[\u{1F300}-\u{1FAFF}]|[\u{2600}-\u{27BF}]/gu, "").replace(/~+/g, "!").replace(/\s+/g, " ").trim();
