    let cartX0 = null, cartOff = 0, cartMode = "in", hourLeft = 9999, celebrate = 0, skillT = 0, lookBack = 0, nextLook = 6;
    let lowFx = false, ft = [], lastFlashAt = -9, rush = "", bigText = null;
