  const yieldPct = (p) => (p.dex && p.dex.vol > 0 && p.dex.liqUsd > 0 && p.feePct > 0 ? ((p.dex.vol * (p.feePct / 100) * 365) / p.dex.liqUsd) * 100 : null);
