    if (!w || !isAddr(addr) || !(S.to === "arc" ? DEPLOYED.arc : DEPLOYED[S.to]) || S.from === "solana") { fee.textContent = "—"; return; }
    var to = S.to_addr || (S.to !== "solana" ? me() : "");
